SELECT s.StudentNo, s.FirstName, s.LastName, COUNT(e.CourseNo) AS CoursesTaken
FROM Students s
JOIN Enrollments e ON e.StudentNo = s.StudentNo
GROUP BY s.StudentNo, s.FirstName, s.LastName
ORDER BY CoursesTaken DESC;

-- Only the top student(s), with ties:
SELECT StudentNo, CoursesTaken FROM (
  SELECT StudentNo, COUNT(*) AS CoursesTaken, RANK() OVER (ORDER BY COUNT(*) DESC) AS rnk
  FROM Enrollments GROUP BY StudentNo
) t WHERE rnk = 1;
